package cn.iocoder.yudao.module.zsjos.dal.mysql.review; import cn.iocoder.yudao.framework.mybatis.core.mapper.BaseMapperX; import cn.iocoder.yudao.module.zsjos.dal.dataobject.review.ReviewReportDO; import org.apache.ibatis.annotations.Mapper; import com.baomidou.mybatisplus.core.conditions.query.LambdaQueryWrapper; import java.util.List; @Mapper public interface ReviewReportMapper extends BaseMapperX<ReviewReportDO> { default List<ReviewReportDO> selectByParticipant(Long uid){return selectList(new LambdaQueryWrapper<ReviewReportDO>().and(q->q.eq(ReviewReportDO::getAuthorUserId,uid).or().eq(ReviewReportDO::getReviewerUserId,uid)).orderByDesc(ReviewReportDO::getUpdateTime).orderByDesc(ReviewReportDO::getId));} default int transition(Long id,Integer version,String from,String to){return update(null,new com.baomidou.mybatisplus.core.conditions.update.LambdaUpdateWrapper<ReviewReportDO>().eq(ReviewReportDO::getId,id).eq(ReviewReportDO::getVersion,version).eq(ReviewReportDO::getStatus,from).set(ReviewReportDO::getStatus,to).set(ReviewReportDO::getVersion,version+1));}}
